fn look_for_min(a: &[i32], i: usize) -> usize {
    // Start by assuming the minimum is at index i.
    let mut min_idx = i;
    let mut min_val = a[i];

    // Iterate over the rest of the slice from i+1 to the end.
    for idx in (i + 1)..a.len() {
        // Whenever we find a strictly smaller element, update min_idx and min_val.
        if a[idx] < min_val {
            min_idx = idx;
            min_val = a[idx];
        }
    }

    // Return the index of the minimum element found in the suffix.
    min_idx
}

